// Orbit coordinates adapted from the supplied shadcn-studio block; keep them aligned with the SVG curves.
// Auto-generated from src/assets/svg/hero-leftline.tsx and hero-rightline.tsx.
// Each entry arc-length-resamples the real SVG curve that the matching orbit
// item travels along, starting right where the line's own gradient first
// becomes non-transparent (not the fully-invisible raw SVG edge), so the logo
// always sits exactly on its line with no visible gap at the start.
// Regenerate by re-running the extraction script if the line art changes.
export type HeroOrbitPath = {
  fromX: number
  fromY: number
  dx: number[]
  dy: number[]
}

// hero-leftline.tsx / hero-rightline.tsx viewBox sizes -- the two SVGs are
// placed edge-to-edge (native scale, no stretching) so their convergence
// points meet at HERO_ORBIT_CENTER.
